item.lov_value:
{
    "bot_name": {
        "type": "text",
        "defaultValue": "George",
        "help": "The name of the bot that will be displayed to users.",
        "label": {
            "FRA": "Nom du bot",
            "ENU": "Bot Name"
        },
        "left_column": true
    },
    "data_number": {
        "type": "text",
        "defaultValue": "5",
        "help": "The amount of data per object requested from the AI.",
        "label": {
            "FRA": "Nombre d'éléments à générer",
            "ENU": "Number of items to generate"
        },
        "left_column": true
    },
    "code_max_token": {
        "type": "text",
        "defaultValue": "2000",
        "help": "The maximum number of tokens the bot can handle for all technical calls, including  chart and modules generation.",
        "label": {
            "FRA": "Nombre maximum de jetons pour appels techniques",
            "ENU": "Max Token for Technical Calls"
        }
    },
    "default_max_token": {
        "type": "text",
        "defaultValue": "1500",
        "help": "The maximum number of tokens the bot can handle by default for each interaction.",
        "label": {
            "FRA": "Nombre maximum de jetons par défaut",
            "ENU": "Default Max Token"
        }
    },
    "hist_depth": {
        "type": "text",
        "defaultValue": "3",
        "help": "The number of previous messages the bot will consider when generating a new response.",
        "label": {
            "FRA": "Profondeur de l'historique",
            "ENU": "History Depth"
        },
        "left_column": true
    },
    "provider": {
        "type": "text",
        "defaultValue": "",
        "help": "Name of the model provider, used in the data disclaimer.",
        "label": {
            "FRA": "Fournisseur",
            "ENU": "Provider"
        },
        "left_column": true
    },
    "showDataDisclaimer": {
        "type": "boolean",
        "defaultValue": true,
        "help": "Indicates whether the data disclaimer should be shown to users.",
        "label": {
            "FRA": "Afficher la clause de non-responsabilité des données",
            "ENU": "Show Data Disclaimer"
        },
        "left_column": true
    },
    "model": {
        "type": "select",
        "defaultValue": "",
        "help": "Select the AI model to use for interactions.",
        "label": {
            "FRA": "Modèle",
            "ENU": "Model"
        },
        "left_column": true
    },
    "api_key": {
        "type": "text",
        "defaultValue": "",
        "help": "API key used to authenticate requests to the AI server.",
        "label": {
            "FRA": "Clé API",
            "ENU": "API Key"
        }
    },
    "completion_url": {
        "type": "url",
        "defaultValue": "",
        "help": "URL where text completion requests will be sent.",
        "label": {
            "FRA": "URL de complétion",
            "ENU": "Completion URL"
        }
    },
    "stt_url": {
        "type": "url",
        "defaultValue": "",
        "help": "URL used for speech recognition.",
        "label": {
            "FRA": "URL de la synthèse vocale ",
            "ENU": "Speech to text URL"
        }
    },
    "ping_url": {
        "type": "url",
        "defaultValue": "",
        "help": "URL used to check the availability of the AI server.",
        "label": {
            "FRA": "URL de ping",
            "ENU": "Ping URL"
        }
    }

}
